'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'
import { useSatinLabels } from '@/registry/satin/ui/labels'
import { MessageActions, type MessageFeedback } from '@/registry/satin/ui/message-actions'
import { Thinking, type ThinkingStep } from '@/registry/satin/ui/thinking'

/**
 * Message, 1:1 with the uiKit Message docs view (3890:70165), composed from `_chat/userMessage`
 * (901:20155), `_chat/source` and `_chat/answerActions` (901:20164, see MessageActions).
 *
 * user: a right-aligned bubble (component/message/bubble-bg: action/inverse in Light, a light grey in
 * Dark; 12px corners, 4px bottom-right), 12 × 8
 * padding, text/on-inverse 13/19.5, wrapping at 256px of text. A source card sits 8px above
 * it: bg/canvas, border/subtle, radius 10, 16px logo, title medium 13/18, url 12/12 muted.
 *
 * assistant: no bubble, so long answers read like a document — text/default 13/19.5, with
 * the collapsed Thinking above and the actions below, 12px apart.
 */
export interface MessageSource {
  /** The page or message title, "Q3 pipeline review". */
  title: React.ReactNode
  /** Shown under the title, "docs.sature.app/q3-review". */
  url?: React.ReactNode
  /** A 16px logo or favicon. */
  icon?: React.ReactNode
  /** Makes the card a link. */
  href?: string
}

export interface MessageProps extends React.ComponentProps<'div'> {
  role?: 'user' | 'assistant'
  /** The steps the agent ran; shows a collapsed Thinking above an assistant answer. */
  thinking?: ThinkingStep[]
  /** The summary on that Thinking header. Defaults to the `thoughtForAMoment` label. */
  thinkingLabel?: React.ReactNode
  /** A page or message the user brought in, shown as a card above their bubble. */
  source?: MessageSource
  /** Feedback, copy and share under an assistant answer. Off while it streams. */
  actions?: boolean
  timestamp?: string
  onFeedback?: (value: MessageFeedback) => void
  onCopy?: () => void
  onShare?: () => void
}

export function Message({
  role = 'assistant',
  thinking,
  thinkingLabel,
  source,
  actions = true,
  timestamp,
  onFeedback,
  onCopy,
  onShare,
  className,
  children,
  ...props
}: MessageProps) {
  const labels = useSatinLabels()
  if (role === 'user') {
    return (
      <div data-slot="message" data-role="user" className={cn('sa:flex sa:flex-col sa:items-end sa:gap-2', className)} {...props}>
        {source && <SourceCard source={source} />}
        <div className="sa:max-w-full sa:rounded-xl sa:rounded-ee-xs sa:bg-component-message-bubble-bg sa:px-3 sa:py-2">
          <div className="sa:max-w-64 sa:text-body sa:break-words sa:text-text-on-inverse">{children}</div>
        </div>
      </div>
    )
  }

  return (
    <div data-slot="message" data-role="assistant" className={cn('sa:flex sa:flex-col sa:items-start sa:gap-3', className)} {...props}>
      {thinking && thinking.length > 0 && <Thinking state="collapsed" label={thinkingLabel ?? labels.thoughtForAMoment} steps={thinking} />}
      <div className="sa:w-full sa:text-body sa:break-words sa:text-text-default">{children}</div>
      {actions && <MessageActions timestamp={timestamp} onFeedback={onFeedback} onCopy={onCopy} onShare={onShare} />}
    </div>
  )
}

function SourceCard({ source }: { source: MessageSource }) {
  const body = (
    <>
      {source.icon && <span className="sa:flex sa:size-4 sa:shrink-0 sa:items-center sa:justify-center sa:[&>*]:size-4">{source.icon}</span>}
      <span className="sa:flex sa:min-w-0 sa:flex-col sa:overflow-clip sa:whitespace-nowrap">
        <span className="sa:truncate sa:text-sm sa:leading-[18px] sa:font-medium sa:text-text-default">{source.title}</span>
        {source.url != null && (
          <span className="sa:truncate sa:text-xs sa:leading-3 sa:tracking-normal sa:text-text-muted">{source.url}</span>
        )}
      </span>
    </>
  )
  const cls = 'sa:flex sa:max-w-full sa:items-center sa:gap-2.5 sa:overflow-clip sa:rounded-lg sa:border sa:border-border-subtle sa:bg-bg-canvas sa:py-2 sa:ps-2.5 sa:pe-3'
  return source.href ? (
    <a href={source.href} className={cls}>
      {body}
    </a>
  ) : (
    <div className={cls}>{body}</div>
  )
}
